const process = require('process');
const rawText = $json?.candidates?.[0]?.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error('Gemini 返回里没有 candidates[0].content.parts[0].text');
}

function extractJsonText(text) {
  const tick = String.fromCharCode(96);
  const fence = tick + tick + tick;
  const fencedJson = new RegExp(fence + 'json\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fencedAny = new RegExp(fence + '\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fenced = text.match(fencedJson) || text.match(fencedAny);
  if (fenced?.[1]) return fenced[1].trim();
  const startObj = text.indexOf('{');
  const endObj = text.lastIndexOf('}');
  if (startObj >= 0 && endObj > startObj) {
    return text.slice(startObj, endObj + 1).trim();
  }
  const startArr = text.indexOf('[');
  const endArr = text.lastIndexOf(']');
  if (startArr >= 0 && endArr > startArr) {
    return text.slice(startArr, endArr + 1).trim();
  }
  return text.trim();
}

let parsed;
try {
  parsed = JSON.parse(extractJsonText(rawText));
} catch (error) {
  // Build redacted snippet for safe logging/storage
  const _rawSnippet = String(rawText || '')
    .replace(/Authorization:[^\n\r]+/gi, '[REDACTED]')
    .replace(/Bearer\s+\S+/gi, '[REDACTED]')
    .replace(/AIzaSy[A-Za-z0-9_-]{30,}/g, '[REDACTED]')
    .replace(/sk-[A-Za-z0-9]{20,}/g, '[REDACTED]')
    .replace(/Kie[A-Za-z0-9_-]{10,}/g, '[REDACTED]')
    .slice(0, 300);
  try {
    const _fs = require('fs');
    const _path = require('path');
    const _os = require('os');
    const _dataRoot = process.env.WORKFLOW_DATA_ROOT || (require('process').platform === 'win32' ? require('path').join(require('process').env.APPDATA || require('path').join(require('process').env.USERPROFILE || require('process').env.HOME || require('os').homedir(), 'AppData', 'Roaming'), 'AI Video', 'workflow-data') : require('path').join(require('os').homedir(), 'Library', 'Application Support', 'AI Video', 'workflow-data'));
    const _stateDir = _path.join(_dataRoot, '.n8n-local-cache', 'project-state');
    _fs.mkdirSync(_stateDir, { recursive: true });
    let _projId = null;
    try { _projId = $json.project_id || null; } catch (_e) {}
    if (!_projId) { try { _projId = ($('Edit Fields1').first().json || {}).project_id || null; } catch (_e) {} }
    if (!_projId) { try { const _s = $('加载默认测试图片').first().json || {}; _projId = _s.project_id || null; } catch (_e) {} }
    if (!_projId) { try { const _s = $('Merge1').first().json || {}; _projId = _s.project_id || null; } catch (_e) {} }
    if (_projId) {
      const _statePath = _path.join(_stateDir, 'project_' + String(_projId).replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json');
      const _existing = (() => { try { return JSON.parse(_fs.readFileSync(_statePath, 'utf8')); } catch (_e) { return {}; } })();
      if (_existing.status !== 'waiting_for_concept_selection' && _existing.status !== 'concept_selected') {
        const _now = new Date().toISOString();
        _fs.writeFileSync(_statePath, JSON.stringify({
          ..._existing,
          project_id: _projId,
          stage: 'creative_direction',
          status: 'failed',
          error_type: 'NON_JSON_MODEL_RESPONSE',
          user_message: '创意方向生成失败：模型返回了非结构化结果，无法解析。建议重新提交；连续失败请导出诊断包检查 API Key 和余额。',
          technical_message: 'NON_JSON_MODEL_RESPONSE: ' + error.message,
          workflow_id: 'rKHHjD2QBlL6EhaM',
          raw_response_summary: _rawSnippet,
          created_at: _existing.created_at || _now,
          updated_at: _now,
        }, null, 2));
      }
    }
  } catch (_) {}
  throw new Error('NON_JSON_MODEL_RESPONSE: 模型返回了非合法 JSON。内容前80字：' + _rawSnippet.slice(0, 80) + '…\n解析错误：' + error.message);
}

// 只读取方向级顶层字段，忽略模型可能额外输出的内容
let result;
if (Array.isArray(parsed)) {
  result = parsed[0] || {};
} else {
  result = parsed || {};
}

const productUnderstanding = result.product_understanding || {};
const audiencePersona = result.audience_persona || {};
const tiktokContentStrategy = result.tiktok_content_strategy || {};
const rawCreativeConceptsArr = Array.isArray(result.creative_concepts) ? result.creative_concepts : [];

const source = $('加载默认测试图片').first().json || $('Merge1').first().json || $('Edit Fields1').first().json || {};
const prompts = $('Prompt Library').first().json || {};
const mapping = prompts.creative_task_type_mapping || {};
const creativeTaskType = source.creative_task_type || '';
function resolveCreativeTaskTypeRules(mapping, rawType) {
  const key = String(rawType || '').trim();
  if (mapping?.[key]) return mapping[key];
  const text = key.toLowerCase();
  const isOotd = /(ootd|outfit|fit\s*check|lookbook|grwm|穿搭|上身|试穿|服饰展示|风格展示|搭配展示|度假风|通勤风|街拍风|模特展示)/i.test(text);
  if (isOotd) return mapping?.['OOTD穿搭展示'] || mapping?.['穿搭展示'] || mapping?.['风格展示'] || {};
  return {};
}
const typeRules = resolveCreativeTaskTypeRules(mapping, creativeTaskType);
const rawCreativeConcepts = rawCreativeConceptsArr;
const creativeConcepts = rawCreativeConcepts.map((concept, index) => ({
  concept_id: concept.concept_id || ('concept_' + String(index + 1).padStart(2, '0')),
  concept_name: concept.concept_name || concept.direction_name || concept.direction || ('创意方向 ' + (index + 1)),
  creative_form: concept.creative_form || concept.video_type || '',
  video_type: concept.video_type || typeRules.video_type || '',
  core_selling_angle: concept.core_selling_angle || concept.visual_hook || concept.hook_visual || concept.selling_point_focus || concept.voiceover_focus || '',
  target_user: concept.target_user || concept.audience_focus || concept.character_status || concept.persona_and_scene || '',
  pain_point: concept.pain_point || '',
  usage_scene: concept.usage_scene || concept.scene_atmosphere || concept.scene_vibe || concept.character_and_scene || concept.persona_and_scene || '',
  visual_expression: concept.visual_expression || concept.camera_performance || concept.camera_movement || concept.wearing_and_mood || '',
  hook_strategy: concept.hook_strategy || concept.visual_hook || concept.hook_visual || '',
  why_it_fits_tiktok: concept.why_it_fits_tiktok || concept.scene_atmosphere || concept.scene_vibe || concept.voiceover_focus || '',
  recommended_grid: concept.recommended_grid || typeRules.recommended_grid || '6_grid',
  risk_notes: concept.risk_notes || '',
  score: concept.score || {},
  original_direction_name: concept.direction_name || concept.direction || '',
  original_payload: concept,
}));
const recommendedGrid = creativeConcepts[0]?.recommended_grid || typeRules.recommended_grid || '6_grid';

function pickImagePaths(input) {
  if (Array.isArray(input.product_image_local_paths) && input.product_image_local_paths.length > 0) {
    return input.product_image_local_paths;
  }
  if (Array.isArray(input.默认测试图片路径) && input.默认测试图片路径.length > 0) {
    return input.默认测试图片路径;
  }
  if (Array.isArray(input.product_images_meta)) {
    const directPaths = input.product_images_meta
      .map((entry) => (typeof entry === 'string' ? entry : entry?.path || ''))
      .filter(Boolean);
    if (directPaths.length > 0) {
      return directPaths;
    }
  }
  return [];
}

const imagePaths = pickImagePaths(source);

return [
  {
    json: {
      project_id: source.project_id || '',
      product_name: source.product_name || '',
      product_desc: source.product_desc || '',
      target_market: source.target_market || '',
      target_language: source.target_language || '',
      creative_task_type: creativeTaskType,
      creative_task_type_rules_json: JSON.stringify(typeRules || {}),
      reference_case_url: source.reference_case_url || '',
      submitted_at: source.submitted_at || '',
      product_images_meta: source.product_images_meta || [],
      product_image_local_paths: imagePaths,
      product_image_count: Number(source.product_image_count || source.image_count || imagePaths.length || 0),
      product_consistency_rule: source.product_consistency_rule || 'Uploaded product images are authoritative. Use the white-background/product-only or primary product reference as product identity source of truth; supporting images guide context only.',
      image_1_path: imagePaths[0] || '',
      image_2_path: imagePaths[1] || '',
      director_status: 'concept_generated',
      status: 'waiting_for_concept_selection',
      product_understanding_json: JSON.stringify(productUnderstanding),
      audience_persona_json: JSON.stringify(audiencePersona),
      tiktok_content_strategy_json: JSON.stringify(tiktokContentStrategy),
      creative_concepts_json: JSON.stringify(creativeConcepts),
      concept_count: creativeConcepts.length,
      recommended_grid: recommendedGrid,
      created_at: new Date().toISOString()
    }
  }
];

const input = $input.item.json;

// 取出导演层生成的创意方向数组字符串
const rawConcepts = input.creative_concepts_json;

if (!rawConcepts) {
  throw new Error('creative_concepts_json 为空，无法提取选中方向');
}

let concepts;
try {
  concepts = JSON.parse(rawConcepts);
} catch (error) {
  throw new Error('creative_concepts_json 不是合法 JSON: ' + error.message);
}

if (!Array.isArray(concepts) || concepts.length === 0) {
  throw new Error('creative_concepts_json 解析后不是有效数组');
}

// 手动选择的创意方向 index
const selectedIndex = Number(input.selected_concept_index ?? 0);

if (selectedIndex < 0 || selectedIndex >= concepts.length) {
  throw new Error(`selected_concept_index 超出范围，当前值: ${selectedIndex}`);
}

// 真正提取选中的那个创意方向
const selectedConcept = concepts[selectedIndex];

return [
  {
    json: {
      // 基础信息继续保留
      project_id: input.project_id || '',
      product_name: input.product_name || '',
      target_market: input.target_market || '',
      target_language: input.target_language || '',
      creative_task_type: input.creative_task_type || '',
      director_status: input.director_status || '',

      // 如果你后面脚本层还想继续参考导演层整体理解，这几个也保留
      product_understanding_json: input.product_understanding_json || '',
      audience_persona_json: input.audience_persona_json || '',
      tiktok_content_strategy_json: input.tiktok_content_strategy_json || '',
      creative_concepts_json: input.creative_concepts_json || '',

      // 这一步新增的核心：选中的那个创意方向
      selected_concept_index: selectedIndex,
      selected_concept_name:
        input.selected_concept_name || selectedConcept.concept_name || '',
      selected_concept_json: JSON.stringify(selectedConcept),
      selected_concept: selectedConcept,

      // 其余辅助字段
      concept_count: input.concept_count || concepts.length,
      created_at: input.created_at || ''
    }
  }
];

const fs = require('fs');
const item = $input.first();
const binary = item.binary || {};

function readImageBase64(binaryKey, pathValue) {
  if (pathValue && fs.existsSync(pathValue)) {
    return fs.readFileSync(pathValue);
  }
  try {
    return this.helpers.getBinaryDataBuffer(0, binaryKey);
  } catch (error) {
    throw error;
  }
}

const image1Buffer = await readImageBase64.call(this, 'product_images_0', item.json.image_1_path || '');
const image2Buffer = await readImageBase64.call(this, 'product_images_1', item.json.image_2_path || '');

const image1Base64 = image1Buffer.toString('base64');
const image2Base64 = image2Buffer.toString('base64');

const mime1 = binary.product_images_0?.mimeType || item.json.image_1_mime || 'image/jpeg';
const mime2 = binary.product_images_1?.mimeType || item.json.image_2_mime || 'image/jpeg';

function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const prompts = $('Prompt Library').first().json;
const s = prompts.script;

const userText = tpl(s.user_template, {
  project_id: item.json.project_id,
  product_name: item.json.product_name,
  target_market: item.json.target_market,
  target_language: item.json.target_language,
  creative_task_type: item.json.creative_task_type,
  product_understanding_json: item.json.product_understanding_json || '',
  audience_persona_json: item.json.audience_persona_json || '',
  tiktok_content_strategy_json: item.json.tiktok_content_strategy_json || '',
  selected_concept_name: item.json.selected_concept_name,
  selected_concept_json: item.json.selected_concept_json || '',
});

const hardConstraintBlock = [
  '',
  '【Form 业务硬约束】',
  '- target_market 必须严格使用：' + (item.json.target_market || ''),
  '- target_language 必须严格使用：' + (item.json.target_language || ''),
  '- creative_task_type 必须严格使用：' + (item.json.creative_task_type || ''),
  '- creative_task_type_rules：' + (item.json.creative_task_type_rules_json || '{}'),
  '- selected_concept 是人工选择后的硬约束，不允许推翻。',
].join('\n');

return [
  {
    json: {
      request_body: {
        system_instruction: {
          parts: [{ text: s.system_instruction }],
        },
        contents: [
          {
            role: 'user',
            parts: [
              { text: userText + hardConstraintBlock },
              { inline_data: { mime_type: mime1, data: image1Base64 } },
              { inline_data: { mime_type: mime2, data: image2Base64 } },
            ],
          },
        ],
        generationConfig: s.generation_config,
      },
    },
  },
];

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
function extractFirstJsonValue(text) {
  const raw = String(text || '').trim();
  if (!raw) return '{}';

  const tick = String.fromCharCode(96);
  const fence = tick + tick + tick;
  const fencedJson = new RegExp(fence + 'json\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fencedAny = new RegExp(fence + '\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fenced = raw.match(fencedJson) || raw.match(fencedAny);
  const source = fenced?.[1] ? fenced[1].trim() : raw;

  for (const start of [source.indexOf('{'), source.indexOf('[')].filter((x) => x >= 0).sort((a, b) => a - b)) {
    const open = source[start];
    const close = open === '{' ? '}' : ']';
    let depth = 0;
    let inString = false;
    let escape = false;
    for (let i = start; i < source.length; i++) {
      const ch = source[i];
      if (inString) {
        if (escape) {
          escape = false;
        } else if (ch === '\\') {
          escape = true;
        } else if (ch === '"') {
          inString = false;
        }
        continue;
      }
      if (ch === '"') {
        inString = true;
      } else if (ch === open) {
        depth++;
      } else if (ch === close) {
        depth--;
        if (depth === 0) return source.slice(start, i + 1).trim();
      }
    }
  }

  return source;
}

let parsed = {};
try {
  parsed = JSON.parse(extractFirstJsonValue(raw));
} catch (error) {
  throw new Error('脚本框架生成返回无法提取合法 JSON: ' + error.message + '，原始返回前800字=' + String(raw).slice(0, 800));
}

// 尽量从上游节点取基础信息
const source =
  $('Code in JavaScript').first()?.json ||
  $('Edit Fields3').first()?.json ||
  $('脚本请求体组装').first()?.json ||
  {};

return [
  {
    json: {
      project_id: source.project_id || '',
      product_name: source.product_name || '',
      target_market: source.target_market || '',
      target_language: source.target_language || '',
      creative_task_type: source.creative_task_type || '',

      selected_concept_name_original: parsed.script_overview?.selected_concept_name_original || '',
      script_concept_label: parsed.script_overview?.script_concept_label || '',
      script_goal: parsed.script_overview?.script_goal || '',
      visual_style: parsed.script_overview?.visual_style || '',
      identified_product_type: parsed.script_overview?.identified_product_type || '',
      product_presentation_logic: parsed.script_overview?.product_presentation_logic || '',
      core_visual_focus: parsed.script_overview?.core_visual_focus || '',
      total_shots: parsed.script_overview?.total_shots || 0,
      hook_strategy: parsed.script_overview?.hook_strategy || '',

      full_script_json: JSON.stringify(parsed),
      created_at: new Date().toISOString(),

      shots: parsed.shots || []
    }
  }
];

const shots = $json.shots || [];

return shots.map((shot, index) => {
  return {
    json: {
      project_id: $json.project_id || '',
      selected_concept_name_original: $json.selected_concept_name_original || '',
      script_concept_label: $json.script_concept_label || '',

      shot_id: shot.shot_id || '',
      shot_order: index + 1,
      stage: shot.stage || '',
      duration: shot.duration || '',
      scene_setting: shot.scene_setting || '',
      visual_action: shot.visual_action || '',
      product_state: shot.product_state || '',
      camera_movement: shot.camera_movement || '',
      expression_focus: shot.expression_focus || '',
      optional_voiceover_local: shot.optional_voiceover_local || '',
      continuity_requirements: shot.continuity_requirements || '',

      created_at: new Date().toISOString()
    }
  };
});

const fs = require('fs');
const item = $input.first();
const json = item.json;
const binary = item.binary || {};

let image1Base64 = json.image_1_base64 || '';
let image2Base64 = json.image_2_base64 || '';

if (!image1Base64 && json.image_1_path && fs.existsSync(json.image_1_path)) {
  image1Base64 = fs.readFileSync(json.image_1_path).toString('base64');
}

if (!image2Base64 && json.image_2_path && fs.existsSync(json.image_2_path)) {
  image2Base64 = fs.readFileSync(json.image_2_path).toString('base64');
}

try {
  const img1 = await this.helpers.getBinaryDataBuffer(0, 'product_images_0');
  image1Base64 = img1.toString('base64');
} catch (e) {}

try {
  const img2 = await this.helpers.getBinaryDataBuffer(0, 'product_images_1');
  image2Base64 = img2.toString('base64');
} catch (e) {}

const mime1 = binary.product_images_0?.mimeType || json.image_1_mime || 'image/jpeg';
const mime2 = binary.product_images_1?.mimeType || json.image_2_mime || 'image/jpeg';

const shots = json.shots || [];
const expectedTotalPanels = shots.length;
const expectedLayoutLabel = '6-panel (3x2, target 27:32)';

if (expectedTotalPanels !== 6) {
  throw new Error('分镜提示词生成前校验失败：当前工作流已强制六宫格，shots 数量必须为 6，实际为 ' + expectedTotalPanels);
}

let fullScriptJson = {
  script_overview: {
    selected_concept_name_original: json.selected_concept_name_original || '',
    script_concept_label: json.script_concept_label || '',
    script_goal: json.script_goal || '',
    visual_style: json.visual_style || '',
    identified_product_type: json.identified_product_type || '',
    product_presentation_logic: json.product_presentation_logic || '',
    core_visual_focus: json.core_visual_focus || '',
    total_shots: json.total_shots || 6,
    hook_strategy: json.hook_strategy || '',
  },
  shots,
};

if (json.full_script_json) {
  try {
    fullScriptJson = JSON.parse(json.full_script_json);
  } catch (e) {}
}

function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const prompts = $('Prompt Library').first().json;
const sb = prompts.storyboard;

const userText = tpl(sb.user_template, {
  project_id: json.project_id || '',
  product_name: json.product_name || '',
  target_market: json.target_market || '',
  target_language: json.target_language || '',
  creative_task_type: json.creative_task_type || '',
  selected_concept_name_original: json.selected_concept_name_original || '',
  script_concept_label: json.script_concept_label || '',
  script_goal: json.script_goal || '',
  visual_style: json.visual_style || '',
  identified_product_type: json.identified_product_type || '',
  product_presentation_logic: json.product_presentation_logic || '',
  core_visual_focus: json.core_visual_focus || '',
  hook_strategy: json.hook_strategy || '',
  expected_total_panels: String(expectedTotalPanels),
  expected_layout_label: expectedLayoutLabel,
  full_script_json: JSON.stringify(fullScriptJson, null, 2),
  shots_json: JSON.stringify(shots, null, 2),
});

const hardConstraintBlock = [
  '',
  '【Form 业务硬约束】',
  '- target_market 必须严格使用：' + (json.target_market || ''),
  '- target_language 必须严格使用：' + (json.target_language || ''),
  '- creative_task_type 必须严格使用：' + (json.creative_task_type || ''),
  '- creative_task_type_rules：' + (json.creative_task_type_rules_json || '{}'),
  '- recommended_grid：' + (json.recommended_grid || '6_grid'),
  '- selected_concept 是人工选择后的硬约束，不允许推翻。',
].join('\n');

return [
  {
    json: {
      request_body: {
        system_instruction: {
          parts: [{ text: sb.system_instruction }],
        },
        contents: [
          {
            role: 'user',
            parts: [
              { text: userText + hardConstraintBlock },
              { inline_data: { mime_type: mime1, data: image1Base64 } },
              { inline_data: { mime_type: mime2, data: image2Base64 } },
            ],
          },
        ],
        generationConfig: sb.generation_config,
      },
    },
  },
];

