  if (errCode !== undefined && errMsg) {
    const hint =
      String(errCode) === '422' ? '模型不支持或参数错误' :
      String(errCode) === '401' ? 'API Key 无效' :
      String(errCode) === '403' ? '账户权限不足或余额不足' :
