  if (payload.error) {
    const e = payload.error;
    throw new Error(`API 错误: ${typeof e === 'string' ? e : (e.message || JSON.stringify(e))}`);
  }
}

const content = payload?.choices?.[0]?.message?.content ?? payload?.message?.content ?? '';
